def read_body_file(file_arg: str) -> bytes:
    """读取正文文件，校验存在性、普通文件与 UTF-8 可解码性。"""
    path = Path(file_arg)
    if not path.is_file():
        raise KBError(f"正文文件不存在或不是普通文件: {file_arg}")
    data = path.read_bytes()
    try:
        data.decode("utf-8")
    except UnicodeDecodeError:
        raise KBError(f"正文无法按 UTF-8 解码: {file_arg}")
    return data

